window.products.push({"id":877532,"name":"Animal Den Rottweiler Security Force Sign","category":"homeandappliances","retail price":13.49,"sale price":null,"image":"https://m.media-amazon.com/images/I/51ga6Gu8ZiL._AC_.jpg","description":"Our Rottweiler Security Force Sign will look great outdoors or indoors. Made from high impact styrene, this durable and weather resistant Rottweiler Security Force Sign is both functional and fun. Easy to install, each sign can easily be mounted to your post, wall, deck, fence, etc. Each Rottweiler Security Force Sign measures approximately 11 x 11 inches.","images":["https://m.media-amazon.com/images/I/51ga6Gu8ZiL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Animal Den","source_asin":"B00IOXSZQG","category_path":"Home & Kitchen"},"sku":"BM-877532","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00IOXSZQG","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00IOXSZQG","price_pending":true,"merchant_ready":false});
